/* From Uiverse.io by bedirhan-arslan  - Tags: simple, form, hover, active, input, rounded, smooth */
.__UIV_SCOPE__ .formField {
  margin: 10px;
  position: relative;
}

.__UIV_SCOPE__ .formField input {
  padding: 10px 15px;
  outline: none;
  border: none;
  border-radius: 5px;
  background-color: #f1f1f1;
  color: #333;
  font-size: 16px;
  font-weight: 550;
  transition: 0.3s ease-in-out;
  box-shadow: 0 0 0 5px transparent;
}

.__UIV_SCOPE__ .formField input:hover,
.__UIV_SCOPE__ .formField input:focus {
  box-shadow: 0 0 0 2px #333;
}

.__UIV_SCOPE__ .formField span {
  position: absolute;
  left: 0;
  top: 0;
  padding: 8px 15px;
  color: #333;
  font-size: 16px;
  font-weight: 600;
  transition: 0.3s ease-in-out;
  pointer-events: none;
}

.__UIV_SCOPE__ .formField input:focus + span,
.__UIV_SCOPE__ .formField input:valid + span {
  transform: translateY(-32px) translateX(-5px) scale(0.95);
  transition: 0.3s ease-in-out;
}
